import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPageIUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIUser";
import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import typia from "typia";

/**
 * Test retrieving users with different filter conditions and pagination settings.
 *
 * This test validates the backend API responsible for listing users with support for pagination, filtering, and searching.
 * Ensures that pagination parameters (page, limit) are respected, that the API properly filters on role and status, and searches by username/email.
 * Also verifies correct behavior on edge-cases: when the filter returns no results, and when invalid pagination values are used (e.g., negative page number).
 *
 * Step-by-step process:
 * 1. Retrieve first page of users with default limit.
 * 2. Retrieve second page with specific limit and compare non-overlapping records.
 * 3. Retrieve users filtered by a specific role (with dynamically selected role ID from step 1, if available).
 * 4. Retrieve users filtered by status (from an observed status value if available).
 * 5. Search for users by partial username or email from step 1 output.
 * 6. Filter with parameters that should return no results (e.g. search nonsense string).
 * 7. Try invalid pagination parameter (negative page) and verify error or fallback.
 */
export async function test_api_user_list_users_with_various_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Retrieve first page of users with default limit.
  const page1: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
    body: {},
  });
  typia.assert(page1);
  TestValidator.equals("page1 current page")(1)(page1.pagination.current);
  // Save items for later cross-comparison.
  const users = page1.data;
  const pageSize = page1.pagination.limit;

  // 2. Retrieve second page with specific limit and compare non-overlapping records.
  const nextPage: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
    body: { page: 2, limit: pageSize },
  });
  typia.assert(nextPage);
  TestValidator.equals("page2 current page")(2)(nextPage.pagination.current);
  // No overlap expected between page1 and nextPage usernames or ids (if enough data exists)
  if (users.length && nextPage.data.length) {
    for (const u of nextPage.data) {
      if (users.some(x => x.id === u.id)) {
        throw new Error(`User from page 2 duplicated on page 1: ${u.id}`);
      }
    }
  }

  // 3. Retrieve users filtered by a specific role (with dynamically selected role ID from step 1, if any users exist).
  if (users.length > 0) {
    const roleId = users[0].role.id;
    const rolePage: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { role: roleId },
    });
    typia.assert(rolePage);
    for (const user of rolePage.data) {
      TestValidator.equals("user.role.id")(roleId)(user.role.id);
    }
  }

  // 4. Retrieve users filtered by status (use status value from first user if exists).
  if (users.length > 0) {
    const status = users[0].status;
    const statusPage: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { status },
    });
    typia.assert(statusPage);
    for (const user of statusPage.data) {
      TestValidator.equals("user.status")(status)(user.status);
    }
  }

  // 5. Search for users by partial username or email from step 1 output.
  if (users.length > 0) {
    const searchFragment = users[0].username.slice(0, 3);
    const searchPage: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { search: searchFragment },
    });
    typia.assert(searchPage);
    // If at least one, verify it has a matching username or email substring
    for (const user of searchPage.data) {
      const s = searchFragment.toLowerCase();
      if (!user.username.toLowerCase().includes(s)) {
        throw new Error(`Search result does not match username. Got: ${user.username}, search: ${s}`);
      }
    }
  }

  // 6. Filter with parameters that should return no results (e.g. search nonsense string).
  const nonsense = "xyzxyzxyz---no-such-user--";
  const emptyPage: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
    body: { search: nonsense },
  });
  typia.assert(emptyPage);
  TestValidator.equals("no search result")(0)(emptyPage.data.length);
  TestValidator.equals("empty page/records")(0)(emptyPage.pagination.records);

  // 7. Try invalid pagination parameter (negative page) and verify error or fallback.
  try {
    await api.functional.core.users.patch(connection, {
      body: { page: -1 },
    });
    throw new Error("Negative page should throw error or not be allowed");
  } catch (err) {
    // Optionally: check err is correct type or status
  }
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IPageIUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIUser";
import { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";

/**
 * Verify that searching for users using a role filter or partial username
 * returns only appropriate users. Confirm edge cases such as searching
 * for non-existent roles or keywords.
 *
 * Detailed Steps:
 * 1. Create two distinct user roles (e.g., "moderator" and "editor").
 * 2. Register four users:
 *    - 2 users with moderator role ("alex_mod", "james_mod")
 *    - 2 users with editor role ("alex_edit", "maria_edit")
 *    - Usernames designed for partial overlap
 * 3. Filter with moderator role, confirm only moderator users returned.
 * 4. Filter with editor role, confirm only editor users returned.
 * 5. Search for username containing "alex" (should match both roles).
 * 6. Search for username containing non-existent keyword (should return empty).
 * 7. Search with a non-existent role UUID (should return empty).
 * 8. Empty filter returns all four users.
 * 9. Validate structure and correct filtering at each step.
 */
export async function test_api_user_search_role_and_keyword_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two user roles
  const moderatorRole: IUserRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: "moderator",
      description: "Moderator role",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(moderatorRole);
  const editorRole: IUserRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: "editor",
      description: "Editor role",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(editorRole);

  // 2. Create users with those roles and overlapping usernames
  const users: IUser[] = [];
  const userInfos = [
    { username: "alex_mod", email: "alex_mod@e2e.com", role: moderatorRole },
    { username: "james_mod", email: "james_mod@e2e.com", role: moderatorRole },
    { username: "alex_edit", email: "alex_edit@e2e.com", role: editorRole },
    { username: "maria_edit", email: "maria_edit@e2e.com", role: editorRole },
  ];
  for (const info of userInfos) {
    const user: IUser = await api.functional.core.users.post(connection, {
      body: {
        user_role_id: info.role.id,
        username: info.username,
        email: info.email,
        password: "Password123!",
        status: "active",
      } satisfies IUser.ICreate,
    });
    typia.assert(user);
    users.push(user);
  }

  // Utility for extracting expected users by criteria
  const getUserIdsBy = (filter: (u: typeof userInfos[0]) => boolean): Set<string> => {
    return new Set(
      userInfos.filter(filter).map(({ username }) =>
        users.find((u) => u.username === username)!.id,
      ),
    );
  };

  // 3. Filter by moderator role (only moderator users)
  {
    const output: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { role: moderatorRole.id } satisfies IUser.IRequest,
    });
    typia.assert(output);
    const expectedIds = getUserIdsBy((u) => u.role.id === moderatorRole.id);
    const actualIds = new Set(output.data.map((u) => u.id));
    TestValidator.equals("moderator-role filter count")(expectedIds.size)(output.data.length);
    for (const user of output.data) {
      TestValidator.equals("role")(moderatorRole.id)(user.role.id);
      TestValidator.equals("expected-id in role filter")(true)(expectedIds.has(user.id));
    }
  }

  // 4. Filter by editor role (only editor users)
  {
    const output: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { role: editorRole.id } satisfies IUser.IRequest,
    });
    typia.assert(output);
    const expectedIds = getUserIdsBy((u) => u.role.id === editorRole.id);
    const actualIds = new Set(output.data.map((u) => u.id));
    TestValidator.equals("editor-role filter count")(expectedIds.size)(output.data.length);
    for (const user of output.data) {
      TestValidator.equals("role")(editorRole.id)(user.role.id);
      TestValidator.equals("expected-id in role filter")(true)(expectedIds.has(user.id));
    }
  }

  // 5. Filter by partial username "alex" (should match two users across roles)
  {
    const output: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { search: "alex" } satisfies IUser.IRequest,
    });
    typia.assert(output);
    const expectedIds = getUserIdsBy((u) => u.username.includes("alex"));
    TestValidator.equals("alex search count")(expectedIds.size)(output.data.length);
    for (const user of output.data) {
      TestValidator.equals("expected-id in alex search")(true)(expectedIds.has(user.id));
      TestValidator.equals("username includes 'alex'")(true)(user.username.includes("alex"));
    }
  }

  // 6. Search for a non-existent keyword -> should be empty
  {
    const output: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { search: "doesnotexist" } satisfies IUser.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty result for nonexistent search")(0)(output.data.length);
  }

  // 7. Search by non-existent role (random UUID)
  {
    const output: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: { role: "00000000-0000-0000-0000-000000000000" } satisfies IUser.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty result for nonexistent role")(0)(output.data.length);
  }

  // 8. Empty filter (should get all 4 users)
  {
    const output: IPageIUser.ISummary = await api.functional.core.users.patch(connection, {
      body: {} satisfies IUser.IRequest,
    });
    typia.assert(output);
    const expectedIds = new Set(users.map((u) => u.id));
    TestValidator.equals("all-users")(expectedIds.size)(output.data.length);
    for (const user of output.data) {
      TestValidator.equals("user returned in global search")(true)(expectedIds.has(user.id));
    }
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { TestValidator } from "@nestia/e2e";

import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * Test retrieving a user profile by a valid user ID and expect correct profile data. Also attempt to retrieve using an invalid or deleted user ID and expect a 404 error.
 *
 * 1. Register a new user (using POST /core/users) to obtain a valid user ID for testing.
 * 2. Retrieve the user profile using GET /core/users/{id}. Assert that the returned user data matches and is valid.
 * 3. Attempt to retrieve a profile using a non-existent (random) UUID and assert that a 404 error is returned.
 *
 * Business Context: Verifies user detail endpoint both for expected (existing user) and not found (non-existent user) outcomes as required for robust frontend/user management flows.
 */
export async function test_api_user_profile_retrieval_success_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new user
  // NOTE: Requires a valid user_role_id; use a fixture or create one as required by your environment
  const userRoleId = typia.random<string & tags.Format<"uuid">>(); // Replace with known good role ID if needed
  const userCreate: IUser.ICreate = {
    user_role_id: userRoleId,
    username: `user_${Math.random().toString(36).slice(2, 12)}`,
    email: `e2e_${Math.random().toString(36).slice(2, 10)}@test.io`,
    password: "password1!",
    status: "active",
    bio: "This is an end-to-end test user.",
  };
  const created: IUser = await api.functional.core.users.post(connection, {
    body: userCreate,
  });
  typia.assert(created);
  // 2. Retrieve profile by valid ID
  const got: IUser = await api.functional.core.users.getById(connection, {
    id: created.id,
  });
  typia.assert(got);
  TestValidator.equals("id matches")(created.id)(got.id);
  // 3. Retrieve profile by non-existent/invalid ID — expect 404
  await TestValidator.httpError("user not found")(404)(() =>
    api.functional.core.users.getById(connection, {
      id: "00000000-0000-4000-8000-000000000404" as string & tags.Format<"uuid">,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IUser, IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

export async function test_api_core_users_post_edge_and_success_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create user role
  const role: IUserRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: "member",
      description: "End user role for registration E2E test",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(role);

  // 2. Register a new user with all valid fields
  const validUserBody = {
    user_role_id: role.id,
    username: "testuser_" + Math.floor(Math.random() * 100000),
    email: `user_${Date.now()}@test.com`,
    password: "Password123!",
    bio: "Test user bio.",
    status: "active",
  } satisfies IUser.ICreate;
  const user: IUser = await api.functional.core.users.post(connection, {
    body: validUserBody,
  });
  typia.assert(user);
  TestValidator.equals("user.username")(validUserBody.username)(user.username);
  TestValidator.equals("user.email")(validUserBody.email)(user.email);
  TestValidator.equals("user.status")(validUserBody.status)(user.status);
  TestValidator.equals("user.role.id")(role.id)(user.role.id);

  // 3. Missing required fields (e.g., missing username)
  await TestValidator.httpError("missing username")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: role.id,
        // username missing
        email: `unique_${Date.now()}@test.com`,
        password: "Password123!",
        status: "active",
      } as any,
    })
  );
  // (Optionally test other required fields)

  // 4. Invalid email format
  await TestValidator.httpError("invalid email")(400)(() =>
    api.functional.core.users.post(connection, {
      body: {
        user_role_id: role.id,
        username: "invalid_email_user",
        email: "not-an-email",
        password: "Password123!",
        status: "active",
      } satisfies IUser.ICreate,
    })
  );

  // 5. Duplicate username
  await TestValidator.httpError("duplicate username")(409)(() =>
    api.functional.core.users.post(connection, {
      body: {
        ...validUserBody,
        email: `other_${Date.now()}@test.com`, // email must differ
      } satisfies IUser.ICreate,
    })
  );

  // 6. Duplicate email
  await TestValidator.httpError("duplicate email")(409)(() =>
    api.functional.core.users.post(connection, {
      body: {
        ...validUserBody,
        username: validUserBody.username + "_new", // username must differ
      } satisfies IUser.ICreate,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import typia, { tags } from "typia";

/**
 * Test updating a user’s profile data under valid and invalid conditions.
 *
 * - Verifies successful update of user fields (bio, status, user_role_id, email, username).
 * - Checks business rule enforcement: unique username/email, valid email format.
 * - Attempts updating to conflicting/invalid values to ensure proper errors are returned.
 * - Attempts updating a non-existent user to validate 404 error logic.
 *
 * Steps:
 * 1. Create two unique user roles (RoleA, RoleB).
 * 2. Register UserA with RoleA and UserB with RoleB; each has unique email and username.
 * 3. Update UserA's bio, status, and assign RoleB. Confirm updates, persistence, and timestamp change.
 * 4. Individually and together, update UserA's email and username to new valid, unused values. Confirm success each time.
 * 5. Attempt to update UserA's email to UserB's (should 409 conflict).
 * 6. Attempt to update UserA's username to UserB's (should 409 conflict).
 * 7. Attempt to update UserA's email with invalid format (should 400 validation error).
 * 8. Attempt to update a non-existent user ID (should 404 not found).
 */
export async function test_api_user_profile_update_with_valid_and_invalid_conditions(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create user roles
  const roleA: IUserRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: `member-${Date.now()}`,
      description: "General member role (A)",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(roleA);
  const roleB: IUserRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: `moderator-${Date.now()}`,
      description: "Moderator role (B)",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(roleB);

  // Step 2: Register users
  const userA_email = `usera-${Date.now()}@e2e.dev`;
  const userB_email = `userb-${Date.now()}@e2e.dev`;
  const userA_username = `UserA-${Date.now()}`;
  const userB_username = `UserB-${Date.now()}`;
  const userA: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: roleA.id,
      username: userA_username,
      email: userA_email,
      password: "strongPasswordA1!",
      status: "active",
      bio: "First user bio",
    } satisfies IUser.ICreate,
  });
  typia.assert(userA);
  const userB: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: roleB.id,
      username: userB_username,
      email: userB_email,
      password: "strongPasswordB1!",
      status: "active",
      bio: "Second user bio",
    } satisfies IUser.ICreate,
  });
  typia.assert(userB);

  // Step 3: Update UserA's bio, status, and user_role_id
  const updateBio = "Updated BioA";
  const updateStatus = "suspended";
  const bioAndRole: IUser = await api.functional.core.users.putById(connection, {
    id: userA.id,
    body: {
      bio: updateBio,
      status: updateStatus,
      user_role_id: roleB.id,
    } satisfies IUser.IUpdate,
  });
  typia.assert(bioAndRole);
  TestValidator.equals("bio update")(updateBio)(bioAndRole.bio);
  TestValidator.equals("status update")(updateStatus)(bioAndRole.status);
  TestValidator.equals("role update")(roleB.id)(bioAndRole.user_role_id);

  // Confirm timestamp updated
  TestValidator.equals("id")(userA.id)(bioAndRole.id);
  TestValidator.equals("timestamp updated")(
    true,
  )(
    bioAndRole.updated_at !== userA.updated_at,
  );

  // Step 4: Update email/username to unique unused values
  const newEmail = `unique-${Date.now()}@e2e.dev`;
  const newUsername = `NewUserA-${Date.now()}`;
  const upd1 = await api.functional.core.users.putById(connection, {
    id: userA.id,
    body: { email: newEmail } satisfies IUser.IUpdate,
  });
  typia.assert(upd1);
  TestValidator.equals("new email")(newEmail)(upd1.email);
  const upd2 = await api.functional.core.users.putById(connection, {
    id: userA.id,
    body: { username: newUsername } satisfies IUser.IUpdate,
  });
  typia.assert(upd2);
  TestValidator.equals("new username")(newUsername)(upd2.username);
  const upd3 = await api.functional.core.users.putById(connection, {
    id: userA.id,
    body: {
      email: `together-${Date.now()}@e2e.dev`,
      username: `ComboUserA-${Date.now()}`,
    } satisfies IUser.IUpdate,
  });
  typia.assert(upd3); // Just confirm it applies

  // Step 5: Attempt to update UserA's email to UserB's email (should 409)
  await TestValidator.httpError("duplicate email")(409)(() =>
    api.functional.core.users.putById(connection, {
      id: userA.id,
      body: {
        email: userB.email,
      } satisfies IUser.IUpdate,
    }),
  );

  // Step 6: Attempt to update UserA's username to UserB's username (should 409)
  await TestValidator.httpError("duplicate username")(409)(() =>
    api.functional.core.users.putById(connection, {
      id: userA.id,
      body: {
        username: userB.username,
      } satisfies IUser.IUpdate,
    }),
  );

  // Step 7: Invalid email format
  await TestValidator.httpError("invalid email")(400)(() =>
    api.functional.core.users.putById(connection, {
      id: userA.id,
      body: {
        email: "invalidemail.com", // missing @
      } satisfies IUser.IUpdate,
    }),
  );

  // Step 8: Non-existent user update
  await TestValidator.httpError("user not found")(404)(() =>
    api.functional.core.users.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { username: "ghost" } satisfies IUser.IUpdate,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * Test soft-deletion and hard deletion of a user profile.
 *
 * This test verifies the full account deletion workflow:
 * - User is registered
 * - Soft delete is performed (DELETE /core/users/{id}), expecting proper deletion response
 * - Attempted repeated delete returns 404 (already deleted)
 * - Attempt delete on a random (non-existent) ID returns 404
 *
 * Steps:
 * 1. Register a new user
 * 2. Delete the user (soft-delete): Response should signal deletion (id, status), and type-check OK
 * 3. Attempt to delete the same user again: Expect 404 error (not found/already deleted)
 * 4. Attempt to delete a random UUID: Expect 404 error
 */
export async function test_api_user_delete_soft_and_hard_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new user
  const created: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `testuser_${Math.random().toString(36).slice(2,10)}`,
      email: `deltest_${Date.now()}@mail.com`,
      password: "TestPassword!2024",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(created);

  // 2. Soft-delete (DELETE)
  const deleted = await api.functional.core.users.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  // Confirm deletion output references the deleted user
  TestValidator.equals("deleted user id")(created.id)(deleted.id);
  TestValidator.equals("deleted status")("deleted")(deleted.status);

  // 3. Repeat delete: Should result in 404
  await TestValidator.httpError("delete already deleted user should 404")(404)(() =>
    api.functional.core.users.eraseById(connection, {
      id: created.id,
    })
  );

  // 4. Non-existent: random UUID
  await TestValidator.httpError("delete non-existent user should 404")(404)(() =>
    api.functional.core.users.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import { IPageIUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIUserRole";

/**
 * Test listing user roles with various filters and pagination.
 *
 * This test validates the listing (PATCH) functionality for user roles, ensuring:
 * - Successful creation of several user roles (distinct names/descriptions)
 * - Listing returns all roles by default
 * - Role name and description filters return the correct role
 * - Pagination works correctly (with limit)
 * - Searching with a non-existent keyword yields no results
 * - All response types and pagination metadata conform to contract
 *
 * Steps:
 * 1. Create at least three roles with distinct names and descriptions
