 * 1. 5개 이상의 카테고리를 서로 다른 이름/설명/생성일시로 생성한다.
 * 2. page/limit 별 분할 조회 결과, pagination 메타데이터 및 목록 길이를 검증한다.
 * 3. name 값으로 단일/복수 필터 조회 후, 반환 목록이 정확한지 확인한다.
 * 4. description 일부 문자열로 필터링 후 정합성 확인.
 * 5. created_from/created_to 날짜 필터를 조합하여 시간대별 필터가 동작하는지 검증한다.
 * 6. 여러 필터를 조합 및 edge case(없는 이름, 지나치게 큰 limit) 등도 확인한다.
 * 7. 모든 응답의 타입을 typia.assert로 확인한다.
 */
export async function test_api_category_list_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. 카테고리 데이터 6개 생성 (이름, 설명, 시간대 다양)
  const now = new Date();
  const categories: ICategory[] = [];
  const baseCategories = [
    { name: "정치", description: "정치 이슈 토론", offsetDays: 0 },
    { name: "경제", description: "경제 뉴스와 해설", offsetDays: 1 },
    { name: "과학", description: "최신 과학 토픽", offsetDays: 2 },
    { name: "문화", description: "문화와 예술 소식", offsetDays: 3 },
    { name: "IT",   description: "정보기술 트렌드", offsetDays: 4 },
    { name: "기타", description: "기타 모든 주제", offsetDays: 5 },
  ];

  for (const bc of baseCategories) {
    // 백데이트가 필요하면 생성 시간을 임의로 조작해 검증한다는 가정
    // 실제 created_at은 서버가 기록하므로 name 및 description 기반 검증 위주로 수행
    const created: ICategory = await api.functional.core.categories.post(
      connection,
      {
        body: {
          name: `${bc.name}_${Date.now()}`,
          description: bc.description,
        } satisfies ICategory.ICreate,
      },
    );
    typia.assert(created);
    categories.push(created);
  }

  // 2. 페이지네이션 검증 (limit 2씩)
  {
    const output1: IPageICategory = await api.functional.core.categories.patch(
      connection,
      {
        body: {
          page: 1,
          limit: 2,
        } satisfies ICategory.IRequest,
      },
    );
    typia.assert(output1);
    TestValidator.equals("첫 페이지 data length")(2)(output1.data.length);

    const output2: IPageICategory = await api.functional.core.categories.patch(
      connection,
      {
        body: {
          page: 2,
          limit: 2,
        } satisfies ICategory.IRequest,
      },
    );
    typia.assert(output2);
    TestValidator.equals("둘째 페이지 data length")(2)(output2.data.length);

    const output3: IPageICategory = await api.functional.core.categories.patch(
      connection,
      {
        body: {
          page: 3,
          limit: 2,
        } satisfies ICategory.IRequest,
      },
    );
    typia.assert(output3);
    // 마지막 페이지는 2개 또는 2개 미만이 될 수 있음 (6개가 기준)
    TestValidator.equals("셋째 페이지 남은 데이터")(
      categories.length - 4
    )(output3.data.length);
  }

  // 3. name 필터 단일검색 (정치)
  {
    const target = categories.find((c) => c.name.startsWith("정치_"));
    const resp: IPageICategory = await api.functional.core.categories.patch(
      connection,
      {
        body: {
          name: target!.name,
          page: 1,
          limit: 10,
        } satisfies ICategory.IRequest,
      },
    );
    typia.assert(resp);
    TestValidator.equals("정치 name 필터 1건")(1)(resp.data.length);
    TestValidator.equals("정치 name 일치")(target!.id)(resp.data[0].id);
  }

  // 4. description 부분검색 ("이슈")
  {
    const resp: IPageICategory = await api.functional.core.categories.patch(
      connection,
      {
        body: {
          description: "이슈",
          page: 1,
          limit: 10,
        } satisfies ICategory.IRequest,
      },
    );
    typia.assert(resp);
    // "정치 이슈 토론"에만 해당
    TestValidator.equals("description = '이슈' 필터 1건")(1)(resp.data.length);
  }

  // 5. 기간(created_from, created_to) 필터 (created_from: now-2day, to now+1day)
  {
    const from = new Date(now);
    from.setDate(from.getDate() + 2);
    const to = new Date(now);
    to.setDate(to.getDate() + 4);
    const resp: IPageICategory = await api.functional.core.categories.patch(
      connection,
      {
        body: {
          created_from: from.toISOString() as any, // 타입 특성상 tags.Format
          created_to: to.toISOString() as any,
          page: 1,
          limit: 10,
        } satisfies ICategory.IRequest,
      },
    );
    typia.assert(resp);
    // "과학", "문화", "IT" 등이 시간 기준에 들어간다고 가정
    const inRange = categories.filter((c) => {
      const dt = new Date(c.created_at).getTime();
      return dt >= from.getTime() && dt <= to.getTime();
    });
    TestValidator.equals("기간 필터 갯수 일치")(inRange.length)(resp.data.length);
  }

  // 6. 여러 필터 조합 및 edge case
  {
    // 없는 이름 필터
    const respNone: IPageICategory = await api.functional.core.categories.patch(
      connection,
      { body: { name: "없는카테고리", page: 1, limit: 10 } satisfies ICategory.IRequest },
    );
    typia.assert(respNone);
    TestValidator.equals("없는 name 필터 0건")(0)(respNone.data.length);

    // limit 너무 큰 값
    const respLimit: IPageICategory = await api.functional.core.categories.patch(
      connection,
      { body: { page: 1, limit: 999 } satisfies ICategory.IRequest },
    );
    typia.assert(respLimit);
    // 모든 카테고리가 반환되어야 함
    // 생성한 categories.length와 respLimit.data.length 일치
    TestValidator.equals("모든 데이터 반환")(categories.length)(respLimit.data.length);
  }
}

