import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";
import { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import { IPageIPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPost";

/**
 * Retrieve a paginated and filtered list of posts.
 *
 * This scenario tests complex search/listing on the posts table with filter combinations, pagination, and sort.
 * Data is setup for full filter matrix (per-user/category, and cross-combinations).
 *
 * 1. Create two users
 * 2. Create two categories
 * 3. Create at least four posts covering all user+category combinations
 * 4. Call posts.posts.patch for: no filter, filter by user, by category, by both, and pagination
 * 5. Assert response types and correctness of filtered subset
 * 6. Try invalid/nonexistent filters (expect empty data array)
 * 7. (Optional) Test title/content keyword search for partial matches
 */
export async function test_api_post_list_posts_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two users (create dummy role first)
  const user_role_id = typia.random<string>(); // Assume a valid user_role_id is available; if not, mock or seed
  const user1: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id,
      username: `author1_${Date.now()}`,
      email: `author1_${Date.now()}@example.com`,
      password: "password123",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user1);
  const user2: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id,
      username: `author2_${Date.now()}`,
      email: `author2_${Date.now()}@example.com`,
      password: "password123",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user2);

  // 2. Create two categories
  const category1: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: `CategoryA_${Date.now()}`,
      description: "Test category A",
    } satisfies ICategory.ICreate,
  });
  typia.assert(category1);

  const category2: ICategory = await api.functional.core.categories.post(connection, {
    body: {
      name: `CategoryB_${Date.now()}`,
      description: "Test category B",
    } satisfies ICategory.ICreate,
  });
  typia.assert(category2);

  // 3. Create four posts (every user posts in every category)
  const postMatrix = [
    { author: user1, category: category1, title: "Post 1 by User 1 in Cat A" },
    { author: user1, category: category2, title: "Post 2 by User 1 in Cat B" },
    { author: user2, category: category1, title: "Post 3 by User 2 in Cat A" },
    { author: user2, category: category2, title: "Post 4 by User 2 in Cat B" },
  ];
  const posts: IPost[] = [];
  for (const meta of postMatrix) {
    const post: IPost = await api.functional.posts.posts.post(connection, {
      body: {
        user_id: meta.author.id,
        category_id: meta.category.id,
        title: meta.title,
        content: `Hello from ${meta.title}!`,
      } satisfies IPost.ICreate,
    });
    typia.assert(post);
    posts.push(post);
  }

  // 4a. List all posts (no filters) - should get at least 4, over all combinations
  let page = 1, limit = 2;
  let resp = await api.functional.posts.posts.patch(connection, {
    body: {
      page,
      limit,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  TestValidator.equals("pagination record count > 0")(true)(resp.pagination.records >= 4);
  TestValidator.equals("posts paged by limit")(limit)(resp.data.length);
  // 4b. List posts by user
  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      user_id: user1.id,
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  for (const post of resp.data) TestValidator.equals("filtered by user_id")(user1.id)(post.user_id);
  // 4c. List posts by category
  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      category_id: category2.id,
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  for (const post of resp.data) TestValidator.equals("filtered by category")(category2.id)(post.category_id);
  // 4d. List posts by user+category (intersection)
  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      user_id: user2.id,
      category_id: category2.id,
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  for (const post of resp.data) {
    TestValidator.equals("filtered by user and category")(user2.id)(post.user_id);
    TestValidator.equals("filtered by user and category")(category2.id)(post.category_id);
  }
  // 4e. Pagination beyond first page
  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      page: 2,
      limit,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  TestValidator.equals("page number")(2)(resp.pagination.current);

  // 5. Invalid user_id/category_id - expect valid type, zero data
  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      user_id: "00000000-0000-0000-0000-000000000001",
      page: 1,
      limit: 2,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  TestValidator.equals("empty for unknown user id")(0)(resp.data.length);

  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      category_id: "00000000-0000-0000-0000-000000000001",
      page: 1,
      limit: 2,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  TestValidator.equals("empty for unknown category id")(0)(resp.data.length);

  // 6. Keyword search: partial title match
  resp = await api.functional.posts.posts.patch(connection, {
    body: {
      title: "Post 3",
      page: 1,
      limit: 10,
    } satisfies IPost.IRequest,
  });
  typia.assert(resp);
  for (const post of resp.data) TestValidator.equals("title contains keyword")(true)(post.title.includes("Post 3"));
}

