 * 1. Create a user (author) for the post
 * 2. Create a category
 * 3. Create a post with that user and category
 * 4. Retrieve the post by its ID
 * 5. Assert all fields on the retrieved post match those of creation (including id, user_id, category_id, title, content, timestamps, deleted_at)
 * 6. Validate structure using typia.assert and correct relation linkage
 */
export async function test_api_post_get_post_by_valid_id(connection: api.IConnection): Promise<void> {
