      user_id: user.id,
      category_id: category.id,
      title: "E2E Test Post Title",
      content: "This is the body of the E2E test post.",
    } satisfies IPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("user_id of created post")(user.id)(post.user_id);
