  // 4. Retrieve the post by its ID
  const retrieved: IPost = await api.functional.posts.posts.getById(connection, {
    id: post.id,
  });
  typia.assert(retrieved);

  // 5. Assert all fields match (id, user_id, category_id, title, content, timestamps, deleted_at)
  TestValidator.equals("id")(post.id)(retrieved.id);
  TestValidator.equals("user_id")(post.user_id)(retrieved.user_id);
