  TestValidator.equals("title")(post.title)(retrieved.title);
  TestValidator.equals("content")(post.content)(retrieved.content);
  TestValidator.equals("created_at")(post.created_at)(retrieved.created_at);
  TestValidator.equals("updated_at")(post.updated_at)(retrieved.updated_at);
  TestValidator.equals("deleted_at")(post.deleted_at ?? null)(retrieved.deleted_at ?? null);
}

