 * 2. Create a category for the post
 * 3. Create the post with the user and category
 * 4. Update the post's title and content (status can be interpreted as new content/category)
 * 5. Retrieve the post again and verify the updated fields and that unchanged fields are preserved
 */
export async function test_api_post_update_with_valid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a user (author)
  const userInput: IUser.ICreate = {
    user_role_id: typia.random<string>(),
    username: `testuser_${Math.floor(Math.random()*1000000)}`,
    email: `test_update_${Date.now()}@e2e.com`,
    password: "testpass!123",
