  // 4. Update the post's title and content
  const updateInput: IPost.IUpdate = {
    title: "Updated Post Title",
    content: "This is the updated content."
  };
  const updatedPost: IPost = await api.functional.posts.posts.putById(connection, {
    id: originalPost.id,
    body: updateInput,
  });
  typia.assert(updatedPost);

  // 5. Retrieve and verify the post (simply use updatedPost here – if separate GET, would call it)
  // Check changed fields
  TestValidator.equals("post.id")(originalPost.id)(updatedPost.id);
  TestValidator.equals("title updated")("Updated Post Title")(updatedPost.title);
  TestValidator.equals("content updated")("This is the updated content.")(updatedPost.content);
  TestValidator.equals("user_id is stable")(user.id)(updatedPost.user_id);
  TestValidator.equals("category_id is stable")(category.id)(updatedPost.category_id);
  // Check that updated_at is after or equal to created_at
  TestValidator.less("updated_at >= created_at")(
    originalPost.created_at,
  )(updatedPost.updated_at);
}

