import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";

/**
 * 댓글 목록 페이징/필터링 조회 검증
 *
 * - 페이징, postId/userId별 필터, 정렬 동작 검증 시나리오
 * - 테스트 정확성을 위해 2명 이상의 사용자와 2개의 포스트를 만들고, 여러 조합으로 댓글 다수를 생성
 * - 각 단계를 거치며 반환된 구조와 메타데이터, 페이징 결과가 비즈니스 규약과 맞는지 확인
 *
 * 1. 테스트용 사용자 2명 생성
 * 2. 각 사용자가 포스트 1개 이상씩 생성
 * 3. 각 포스트마다 교차 작성 방식으로 다양한 댓글 생성
 * 4. 댓글 목록:
 *    - 필터 없이 전체 조회
 *    - postId별 조회
 *    - userId별 조회
 *    - 페이징 (limit, offset)
 *    - 정렬 (최신순, 오래된순)
 *    - 각 케이스 예상 결과와 데이터 정합성 검증
 */
export async function test_api_comment_list_comments_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. 테스트용 사용자 2명 생성
  const userRoleId = typia.random<string>(); // 실제 환경에서는 적절한 role-id를 제공해야 함
  const userA: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: "UserA_" + Math.random().toString(36).slice(2),
      email: `usera_${Date.now()}@test.io`,
      password: "pw12345!@#",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(userA);

  const userB: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: "UserB_" + Math.random().toString(36).slice(2),
      email: `userb_${Date.now()}@test.io`,
      password: "pw67890!@#",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(userB);

  // 2. 각 사용자가 포스트 1개 이상씩 생성 (카테고리 id 임의 값 지정)
  const categoryId = typia.random<string>();
  const postA: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: "PostA Title",
      content: "Content of PostA",
      user_id: userA.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postA);

  const postB: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: "PostB Title",
      content: "Content of PostB",
      user_id: userB.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(postB);

  // 3. 각 포스트마다 교차로 여러 개 댓글 생성 (userA와 userB가 상대방 포스트에 남김)
  const comments: IComment[] = [];
  for (let i = 0; i < 3; ++i) {
    // userA가 postB에 댓글
    const c1 = await api.functional.posts.comments.post(connection, {
      body: {
        user_id: userA.id,
        post_id: postB.id,
        content: `CommentA-${i}`,
      } satisfies IComment.ICreate,
    });
    typia.assert(c1);
    comments.push(c1);
    // userB가 postA에 댓글
    const c2 = await api.functional.posts.comments.post(connection, {
      body: {
        user_id: userB.id,
        post_id: postA.id,
        content: `CommentB-${i}`,
      } satisfies IComment.ICreate,
    });
    typia.assert(c2);
    comments.push(c2);
  }
  // 추가: postA, postB 각각에 자기 자신이 댓글 하나 더 남김
  const extraA = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: userA.id,
      post_id: postA.id,
      content: `ExtraA-self-comment`,
    } satisfies IComment.ICreate,
  });
  typia.assert(extraA);
  comments.push(extraA);

  const extraB = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: userB.id,
      post_id: postB.id,
      content: `ExtraB-self-comment`,
    } satisfies IComment.ICreate,
  });
  typia.assert(extraB);
  comments.push(extraB);

  // 4. 다양한 필터/페이징/정렬로 리스트 조회 및 검증
  // 4-1. 전체 댓글 리스트 (필터 없음)
  const listAll: IPageIComment = await api.functional.posts.comments.patch(connection, {
    body: {},
  });
  typia.assert(listAll);
  TestValidator.equals("comments 전체 개수")(comments.length)(listAll.data.length);

  // 4-2. postId별 필터 (예: postA)
  const listByPost: IPageIComment = await api.functional.posts.comments.patch(connection, {
    body: { postId: postA.id },
  });
  typia.assert(listByPost);
  const expectPostAComments = comments.filter((c) => c.post_id === postA.id);
  TestValidator.equals("postA의 댓글 개수")(expectPostAComments.length)(listByPost.data.length);
  TestValidator.equals("postA의 첫 댓글-id")(expectPostAComments[0].id)(listByPost.data[0].id);

  // 4-3. userId별 필터 (예: userB)
  const listByUser: IPageIComment = await api.functional.posts.comments.patch(connection, {
    body: { userId: userB.id },
  });
  typia.assert(listByUser);
  const expectUserBComments = comments.filter((c) => c.user_id === userB.id);
  TestValidator.equals("userB의 댓글 개수")(expectUserBComments.length)(listByUser.data.length);
  TestValidator.equals("userB의 첫 댓글-id")(expectUserBComments[0].id)(listByUser.data[0].id);

  // 4-4. 페이징 테스트 (limit=2, offset=2)
  const paging: IPageIComment = await api.functional.posts.comments.patch(connection, {
    body: { limit: 2, offset: 2 },
  });
  typia.assert(paging);
  TestValidator.equals("paging 개수")(2)(paging.data.length);

  // 4-5. 정렬 (created_at desc, 기본)
  const sortedDesc: IPageIComment = await api.functional.posts.comments.patch(connection, {
    body: { sort: "created_at:desc" },
  });
  typia.assert(sortedDesc);
  for (let i = 1; i < sortedDesc.data.length; ++i) {
    TestValidator.equals("최신 정렬 여부")(
      true,
    )(
      sortedDesc.data[i - 1].created_at >= sortedDesc.data[i].created_at
    );
  }

  // 4-6. 정렬 (created_at asc, 오래된 순)
  const sortedAsc: IPageIComment = await api.functional.posts.comments.patch(connection, {
    body: { sort: "created_at:asc" },
  });
  typia.assert(sortedAsc);
  for (let i = 1; i < sortedAsc.data.length; ++i) {
    TestValidator.equals("오래된 순 정렬 여부")(
      true,
    )(
      sortedAsc.data[i - 1].created_at <= sortedAsc.data[i].created_at
    );
  }
}

