/**
 * Retrieve a paginated, filtered list of votes.
 *
 * This test covers end-to-end the ability to retrieve votes with filters for voter or post,
 * as well as pagination and sorting features.
 * To verify filtering and pagination work, we must set up a scenario where several votes from
 * different users are cast on a post, and then use various filters/queries.
 *
 * 1. Create user1 (voter)
 * 2. Create user2 (another voter)
 * 3. Create a post (by user1)
 * 4. Create votes on the post (some by user1, some by user2, upvote/downvote mix)
 * 5. Retrieve all votes paginated (limit=2, offset=0); verify paging meta and content
 * 6. Retrieve votes filtered by userId (user1); check all user_ids match
 * 7. Retrieve votes filtered by postId; check all post_ids match
 * 8. (If sort available) Retrieve with sorting to validate sort order
 * 9. Assert all response structures/types and pagination meta using typia & TestValidator
 */
export async function test_api_vote_list_votes_with_pagination_and_filters(connection: api.IConnection): Promise<void> {
  // 1. Create user1
  const userRoleId = typia.random<string>(); // Or use a fixture/known role
  const user1: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: `user_vote_test_1_${Date.now()}`,
      email: `vote_test_1_${Date.now()}@test.com`,
      password: "pwtest123!",
      status: "active",
      bio: "Test voter user 1"
    } satisfies IUser.ICreate
  });
  typia.assert(user1);

  // 2. Create user2
  const user2: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: `user_vote_test_2_${Date.now()}`,
      email: `vote_test_2_${Date.now()}@test.com`,
      password: "pwtest123!",
      status: "active",
      bio: "Test voter user 2"
    } satisfies IUser.ICreate
  });
  typia.assert(user2);

  // 3. Create a post (by user1)
  const categoryId = typia.random<string>();
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: "Vote List E2E Test Post",
      content: "This is a post for vote list pagination/filter E2E testing.",
      user_id: user1.id
    } satisfies IPost.ICreate
  });
  typia.assert(post);

  // 4. Cast votes: user1 +1, user2 -1, user2 +1
  const vote1: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user1.id,
      post_id: post.id,
      value: 1
    } satisfies IVote.ICreate
  });
  typia.assert(vote1);

  const vote2: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user2.id,
      post_id: post.id,
      value: -1
    } satisfies IVote.ICreate
  });
  typia.assert(vote2);

  const vote3: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user2.id,
      post_id: post.id,
      value: 1
    } satisfies IVote.ICreate
  });
  typia.assert(vote3);

  // 5. Retrieve all votes paginated (limit=2, offset=0)
  const allVotesPage: IPageIVote = await api.functional.votes.votes.patch(connection, {
    body: {
      offset: 0,
      limit: 2
    } satisfies IVote.IRequest
  });
  typia.assert(allVotesPage);
  TestValidator.equals("pagination.limit")(2)(allVotesPage.pagination.limit);
  TestValidator.equals("pagination.offset")(0)(allVotesPage.pagination.current * allVotesPage.pagination.limit - allVotesPage.pagination.limit);
  TestValidator.equals("data.length")(2)(allVotesPage.data.length);

  // 6. Retrieve votes by user1 (userId filter)
  const user1VotesPage: IPageIVote = await api.functional.votes.votes.patch(connection, {
    body: {
      userId: user1.id
    } satisfies IVote.IRequest
  });
  typia.assert(user1VotesPage);
  for (const v of user1VotesPage.data) {
    TestValidator.equals("vote.user_id == user1.id")(user1.id)(v.user_id);
  }

  // 7. Retrieve votes by postId (all votes should be for our post)
  const postVotesPage: IPageIVote = await api.functional.votes.votes.patch(connection, {
    body: {
      postId: post.id
    } satisfies IVote.IRequest
  });
  typia.assert(postVotesPage);
  for (const v of postVotesPage.data) {
    TestValidator.equals("vote.post_id == post.id")(post.id)(v.post_id);
  }

  // 8. (Optional) Retrieve with explicit sort order (if system supports)
  // For demonstration, try 'sort: "created_at:desc"' if API supports
  const sortedVotesPage: IPageIVote = await api.functional.votes.votes.patch(connection, {
    body: {
      postId: post.id,
      sort: "created_at:desc"
    } satisfies IVote.IRequest
  });
  typia.assert(sortedVotesPage);

  // 9. Confirm general structure, data validity
  for (const v of sortedVotesPage.data) {
    typia.assert(v);
  }
}

