 *
 * This test ensures that a registered user can cast a vote (+1 or -1) on an existing post, and that the vote is correctly created and persisted.
 *
 * Steps:
 * 1. Register an example user (require valid role ID, username, email, password, and status)
 * 2. Create a post authored by that user (using user's id, valid category, and content/title)
 * 3. Create a vote, linking the above user and post (value +1)
 * 4. Validate the vote was created, its fields are correct, and it links both user/post as expected
 *
 * Foreign key consistency (user_id, post_id) is strictly enforced in assertions.
 */
export async function test_api_votes_votes_create_valid_vote(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register user (use a static role_id for test or inject/lookup one if needed)
  const userRoleId = "00000000-0000-0000-0000-000000000001" as const;
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: "vote_tester",
      email: `vote_tester_${Date.now()}@wrtn.io`,
      bio: "Test voter account",
      password: "vote_pw_123!",
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create post linked to new user
  const testCategoryId = "00000000-0000-0000-0000-000000000010" as const;
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      user_id: user.id,
      category_id: testCategoryId,
      title: "Vote Test Post",
      content: "Content for vote test post.",
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast vote (upvote, value=+1)
  const voteValue = 1;
  const vote: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      comment_id: null,
      value: voteValue,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("vote.user_id")(user.id)(vote.user_id);
  TestValidator.equals("vote.post_id")(post.id)(vote.post_id);
  TestValidator.equals("vote.value")(voteValue)(vote.value);
  TestValidator.equals("vote.comment_id")(null)(vote.comment_id);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Ensure the system enforces the rule: only one vote per user per target (post).
 *
 * Try to vote twice for the same post as the same user and ensure the system rejects the second attempt with an error.
 *
 * Step-by-step procedure:
 * 1. Register a user with a unique username, email, and role.
 * 2. Create a new post as the user (requires a valid category_id; assume value is known or mocked).
 * 3. Cast a vote on the post from the user -- expect success.
 * 4. Attempt to cast a second vote for the same post from the same user -- expect a unique constraint error (HTTP 409 or similar).
 * 5. Validate all returned types and error conditions.
 */
export async function test_api_vote_create_vote_with_duplicate_user_target(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register user
  const userRoleId = "11111111-1111-1111-1111-111111111111"; // Use a fixed test role ID (should exist in DB for test env)
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: `e2e_voter_${Date.now()}`,
      email: `e2e_voter_${Date.now()}@test.io`,
      password: "testpass123",
      status: "active",
      bio: "Test voter for duplicate vote test."
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create post (need a valid category_id, mock as fixed UUID for test)
  const categoryId = "22222222-2222-2222-2222-222222222222"; // Should exist in DB for test env
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: categoryId,
      title: `E2E Post for Duplicate Vote Test ${Date.now()}`,
      content: "Test content for vote duplication check.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. First vote (should succeed)
  const vote1: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      value: 1,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote1);

  // 4. Second vote on the same post: must fail due to uniqueness constraint
  await TestValidator.httpError("duplicate user vote on same post should fail")(409)(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id: user.id,
        post_id: post.id,
        value: 1,
      } satisfies IVote.ICreate,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Update the value of an existing vote and verify persistence.
 *
 * Scenario:
 * 1. Register a new user (as voter).
 * 2. Create a new post authored by the user.
 * 3. Cast an upvote (+1) on the post by this user.
 * 4. Update the vote's value to -1 (convert upvote to downvote) via PUT /votes/votes/{id}.
 * 5. Fetch the updated vote and confirm its value has been changed correctly.
 *
 * Business context:
 * This validates not only mutability logic (allowing users to edit their votes) but also
the system's ability to maintain immutable identity/target fields (user, post) while permitting value changes. It further ensures votes stay single-per-user-per-content.
 */
export async function test_api_vote_update_vote_with_valid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      username: `voter_${Math.random().toString(36).substring(2, 10)}`,
      email: `voter_${Math.random().toString(36).substring(2, 10)}@example.com`,
      password: "Test1234!",
      user_role_id: typia.random<string & tags.Format<"uuid">>(),
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a new post authored by this user
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test Voting Post",
      content: "Testing voting business logic.",
      user_id: user.id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. User casts an upvote (+1) on the post
  const vote: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      value: 1,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("Initial vote value")(1)(vote.value);
  TestValidator.equals("Voter ID")(user.id)(vote.user_id);
  TestValidator.equals("Target post ID")(post.id)(vote.post_id);

  // 4. Update the vote's value to -1
  const updated: IVote = await api.functional.votes.votes.putById(connection, {
    id: vote.id,
    body: { value: -1 } satisfies IVote.IUpdate,
  });
  typia.assert(updated);

  // 5. Fetch the updated vote and verify value is now -1 (other fields immutable)
  // (Assume GET /votes/votes/{id} exists as api.functional.votes.votes.getById)
  // If not, "updated" variable already contains the newest state after PUT.
  TestValidator.equals("Updated vote id")(vote.id)(updated.id);
  TestValidator.equals("Voter ID after update")(vote.user_id)(updated.user_id);
  TestValidator.equals("Post ID after update")(vote.post_id)(updated.post_id);
  TestValidator.equals("Vote value after update")(-1)(updated.value);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

export async function test_api_vote_update_invalid_fields(connection: api.IConnection) {
  /**
   * 1. Register a user for voting
   */
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const userInput: IUser.ICreate = {
    user_role_id: userRoleId,
    username: `voter_${Date.now()}`,
    email: `voter_${Date.now()}@test.com`,
    password: "pass1234!",
    status: "active",
  };
  const user: IUser = await api.functional.core.users.post(connection, {
    body: userInput,
  });
  typia.assert(user);

  /**
   * 2. Create a post for the vote target
   */
  const postInput: IPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: `Vote Target Post ${Date.now()}`,
    content: "Vote target.",
    user_id: user.id,
  };
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  /**
   * 3. Submit a legitimate vote to the post
   */
  const voteInput: IVote.ICreate = {
    user_id: user.id,
    post_id: post.id,
    value: 1,
  };
  const vote: IVote = await api.functional.votes.votes.post(connection, {
    body: voteInput,
  });
  typia.assert(vote);

  /**
   * 4. Attempt to update the vote with invalid value (not +1/-1)
   */
  await TestValidator.httpError("vote update - invalid value (not +1/-1)")(400)(() =>
    api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: { value: 0 }, // Not allowed
    }),
  );
  await TestValidator.httpError("vote update - invalid value (too high)")(400)(() =>
    api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: { value: 2 },
    }),
  );
  await TestValidator.httpError("vote update - invalid value (too low)")(400)(() =>
    api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: { value: -2 },
    }),
  );

  /**
   * 5. Attempt to update the vote with a missing required value field
   */
  // @ts-expect-error Purposely omitting the value field for validation test
  await TestValidator.httpError("vote update - missing required value field")(400)(() =>
    api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: {},
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import typia, { tags } from "typia";

/**
 * Attempt to update a vote with a non-existent ID and ensure a 404 is returned.
 *
 * This test validates the backend's error handling when a client attempts to update a vote record with an ID that does not exist in the database. According to business rules, only votes that actually exist (and are owned by the user) may be updated, so the API should respond with a 404 Not Found error for any missing ID.
 *
 * 1. Generate a random UUID to simulate a non-existent vote ID.
 * 2. Create a valid IVote.IUpdate object (e.g., change the value to +1 or -1).
 * 3. Attempt to update the vote by calling SDK: api.functional.votes.votes.putById.
 * 4. Assert that a 404 HTTP error is triggered (resource not found).
 */
export async function test_api_votes_votes_update_non_existent_id_error(
  connection: api.IConnection,
): Promise<void> {
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const updateBody: IVote.IUpdate = {
    value: 1,
  };

  await TestValidator.httpError("update with non-existent vote ID should fail with 404")(404)(() =>
    api.functional.votes.votes.putById(connection, {
      id: nonExistentId,
      body: updateBody,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";
import typia from "typia";

/**
 * Delete a vote by its ID and verify deletion.
 *
 * This test validates the process of casting a vote and then deleting it, ensuring proper DB changes and expected error conditions for deleted resources.
 *
 * 1. Register a new user (vote creator)
 * 2. Create a new post (vote target)
 * 3. Cast a vote on the post by the user
 * 4. Delete the created vote by ID
 * 5. Attempt to lookup the vote, expecting 404 Not Found
 *
 * This ensures both positive (delete response) and negative (retrieval after delete) behaviors.
 */
export async function test_api_vote_delete_and_verify_deletion(connection: api.IConnection): Promise<void> {
  // 1. Register user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      username: `voter_${Date.now()}`,
      email: `voter${Date.now()}@test.com`,
      password: "testpw123",
      user_role_id: "00000000-0000-0000-0000-000000000001", // assuming this exists for test
      status: "active",
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Create a post (as the same user)
  const post: IPost = await api.functional.posts.posts.post(connection, {
    body: {
      user_id: user.id,
      category_id: "00000000-0000-0000-0000-000000000001", // assuming exists
      title: `Test Post for Voting ${Date.now()}`,
      content: "E2E Voting Delete Test Content",
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast a vote on the post
  const vote: IVote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: user.id,
      post_id: post.id,
      value: 1,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);

  // 4. Delete the vote
  const deleteResult: IVote.IDeleteResult = await api.functional.votes.votes.eraseById(connection, {
    id: vote.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("deleted flag should be true")(true)(deleteResult.deleted);
  TestValidator.equals("deleted id should match vote")(vote.id)(deleteResult.id);

  // 5. Retrieval should now fail with 404 (if implemented)
  await TestValidator.httpError("get deleted vote should 404")(404)(() =>
    api.functional.votes.votes.get!(connection, { id: vote.id }),
  );
}

